    //IAR
    public static string ExportToExcelIAR(DataTable dt, DataTable dt1, String ReportTitle, DataTable dt3, DataTable dt2)
    {
        try
        {

            //Get company info
            MiscBll miscBll = new MiscBll();
            string x = miscBll.GetCompanyInformation(Common.ConnString);
            CompanyName = x.Split('|')[0];
            CompanyContactNumber = x.Split('|')[3];
            CompanyAddress = x.Split('|')[5];


            string y = miscBll.GetFormHeader(Common.ConnString);
            header1 = y.Split('|')[0];
            header2 = y.Split('|')[1];
            headerHeight = y.Split('|')[2];
            headerWidth = y.Split('|')[3];

            string invNo = "";
            if (dt3.Rows.Count > 0)
            {
                invNo = dt3.Rows[0]["InvoiceNumber"].ToString();
            }


            using (var workbook = new XLWorkbook())
            {
                var worksheet = workbook.Worksheets.Add("IAR");

                //TITLE START
                var Appendix = worksheet.Range("E1:E1").Merge();
                //worksheet.Cell(1, 5).Value = "Appendix 62";
                Appendix.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                Appendix.Style.Font.FontSize = 11;
                Appendix.Style.Font.Italic = true;

                var Header1 = worksheet.Range("A2:E2").Merge();
                worksheet.Cell(2, 1).Value = header1;
                Header1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                Header1.Style.Font.Bold = true;
                Header1.Style.Font.FontSize = 14;

                var Header2 = worksheet.Range("A3:E3").Merge();
                worksheet.Cell(3, 1).Value = header2;
                Header2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                //Header2.Style.Font.Bold = true;
                Header2.Style.Font.FontSize = 14;

                var IARText = worksheet.Range("A5:E5").Merge();
                worksheet.Cell(5, 1).Value = "INSPECTION AND ACCEPTANCE REPORT";
                IARText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                IARText.Style.Font.Bold = true;
                IARText.Style.Font.FontSize = 16;

                string fileName = "Image\\" + Common.CompanyInfo + "\\FormLogo.png";
                string filePath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, fileName);

                var picture = worksheet.AddPicture(filePath)
                                  .WithPlacement(XLPicturePlacement.FreeFloating)
                                  .MoveTo(20, 20);


                picture.Width = Convert.ToInt32(headerWidth);
                picture.Height = Convert.ToInt32(headerHeight);
                //TITLE END --------------------------------------------------------------------------

                //HEADER START
                var EntiText = worksheet.Cell("A6");
                var ClusText = worksheet.Cell("D6");
                //worksheet.Cell(7, 1).Value = "Entity Name: " + CompanyName;
                //worksheet.Cell(7, 4).Value = "Fund Cluster: ";
                EntiText.Style.Font.Bold = true;
                ClusText.Style.Font.Bold = true;

                worksheet.Cell(8, 1).Value = "Supplier  : " + dt1.Rows[0][0]; 
                worksheet.Cell(8, 4).Value = "IAR No.: " + dt1.Rows[0][2];

                worksheet.Cell(9, 1).Value = "PO No./Date: " + dt1.Rows[0][1];
                string onlyDate = Convert.ToDateTime(dt1.Rows[0][3]).ToString("dd/MM/yyyy");
                worksheet.Cell(9, 4).Value = "Date: " + onlyDate;


                worksheet.Cell(10, 1).Value = "Requisitioning Office/Dept.: " + dt2.Rows[0]["WarehouseName"].ToString(); ;
                worksheet.Cell(10, 4).Value = "Invoice No.: " + invNo;

                //worksheet.Cell(11, 1).Value = "Responsibility Office/Dept.: ";
                worksheet.Cell(11, 4).Value = "Delivery No: " + dt2.Rows[0]["DRNumber"].ToString();

                var AllFormRange = worksheet.Range("A8:E13");
                var AllFormtBorder = AllFormRange.Style.Border;
                AllFormtBorder.OutsideBorder = XLBorderStyleValues.Thin;

                var DetailsLeftRange = worksheet.Range("A8:C11");
                var DetailsLeftBorder = DetailsLeftRange.Style.Border;
                DetailsLeftBorder.OutsideBorder = XLBorderStyleValues.Thin;

                var DetailsRightRange = worksheet.Range("D8:E11");
                var DetailsRightBorder = DetailsRightRange.Style.Border;
                DetailsRightBorder.OutsideBorder = XLBorderStyleValues.Thin;
                //HEADER END --------------------------------------------------------------------------


                //DETAILS START ------------------------------------------------------------------------
