                StockPropText.Style.Font.Bold = true;
                worksheet.Cell(12, 1).Value = "Item No.";

                var DescText = worksheet.Range("B12:C13").Merge();
                DescText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                DescText.Style.Font.Bold = true;
                worksheet.Cell(12, 2).Value = "Description";

                var UnitText = worksheet.Range("D12:D13").Merge();
