                UnitText.Style.Font.Bold = true;
                worksheet.Cell(12, 4).Value = "Unit";

                var QuantText = worksheet.Range("E12:E13").Merge();
                QuantText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                QuantText.Style.Font.Bold = true;
                worksheet.Cell(12, 5).Value = "Quantity";

                int SBorder = 14;
                var footerstart = 26 + dt3.Rows.Count;
                if (dt3.Rows.Count > 0)
                {
                    
                    for (int i = 0; i < dt3.Rows.Count; i++)
                    {
                        var d1 = worksheet.Cell(SBorder, 1);
                        worksheet.Cell(SBorder, 1).Value = i+1;
                        d1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                        d1.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        d1.Style.Alignment.WrapText = true;

                        worksheet.Range("B" + SBorder + ":C" + SBorder).Merge();


                        if (dt3.Rows[i]["Type"].ToString() == "Property")
                        {
                            var d2 = worksheet.Cell(SBorder, 2);
                            worksheet.Cell(SBorder, 2).Value = dt3.Rows[i]["LongDescription"].ToString();
                            d2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                            d2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                            d2.Style.Alignment.WrapText = true;
                        }

                        else
                        {
                            var d2 = worksheet.Cell(SBorder, 2);
                            worksheet.Cell(SBorder, 2).Value = dt3.Rows[i]["Description"].ToString();
                            d2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                            d2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                            d2.Style.Alignment.WrapText = true;
                        }


                        var d3 = worksheet.Cell(SBorder, 4);
                        worksheet.Cell(SBorder, 4).Value = dt.Rows[i]["UnitOfMeasurement"].ToString();
                        d3.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                        d3.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        d3.Style.Alignment.WrapText = true;

                        var d4 = worksheet.Cell(SBorder, 5);
                        worksheet.Cell(SBorder, 5).Value = dt.Rows[i]["Quantity"].ToString();
                        d4.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
                        d4.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                        d4.Style.Alignment.WrapText = true;

                        //worksheet.Range("E" + SBorder + ":D" + SBorder).Merge();

                        SBorder += 1;
                    }
                }

                var DetailsBodyStockRange = worksheet.Range("A14:A" + (footerstart - 1) + "");
                var DetailsBodyStockBorder = DetailsBodyStockRange.Style.Border;
                DetailsBodyStockBorder.OutsideBorder = XLBorderStyleValues.Thin;
                DetailsBodyStockBorder.InsideBorder = XLBorderStyleValues.Thin;

                var DetailsBodyDescRange = worksheet.Range("B14:C" + (footerstart - 1) + "");
