                FooterLeftBorder.RightBorder = XLBorderStyleValues.Thin;

                var FooterBottRange = worksheet.Range("A" + (footerstart) + ":E" + (footerstart + 16) + "");
                var FooterBottBorder = FooterBottRange.Style.Border;
                FooterBottBorder.OutsideBorder = XLBorderStyleValues.Thin;

                var FooterLeftRangeA = worksheet.Range("A" + (footerstart +6) + ":B" + (footerstart + 6) + "");
                var FooterLeftBorderA = FooterLeftRangeA.Style.Border;
                FooterLeftBorderA.BottomBorder = XLBorderStyleValues.Thin;

                var FooterLeftRangeAB = worksheet.Range("A" + (footerstart + 11) + ":E" + (footerstart + 11) + "");
                var FooterLeftBorderAB = FooterLeftRangeAB.Style.Border;
                FooterLeftBorderAB.BottomBorder = XLBorderStyleValues.Thin;

                var InspecText = worksheet.Range("A" + (footerstart) + ":B" + (footerstart) + "").Merge();
                worksheet.Cell(footerstart, 1).Value = "INSPECTION";
                InspecText.Style.Font.Bold = true;
                InspecText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                InspecText.Style.Font.FontSize = 14;

                var AccepText = worksheet.Range("C" + (footerstart) + ":E" + (footerstart) + "").Merge();
                worksheet.Cell(footerstart, 3).Value = "ACCEPTANCE";
                AccepText.Style.Font.Bold = true;
                AccepText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                AccepText.Style.Font.FontSize = 14;

                //var DateInspecText = worksheet.Range("A" + (footerstart + 1) + ":B" + (footerstart + 2) + "").Merge();
                //worksheet.Cell((footerstart + 1), 1).Value = "Date Inspected: ";
                //DateInspecText.Style.Font.Bold = true;


                //var DateAcceptText = worksheet.Range("C" + (footerstart + 1) + ":E" + (footerstart + 2) + "").Merge();
                //worksheet.Cell((footerstart + 1), 4).Value = "Date Received: ";
                //DateAcceptText.Style.Font.Bold = true;

                var InspectCheckText = worksheet.Range("A" + (footerstart + 1) + ":B" + (footerstart + 2) + "").Merge();
                InspectCheckText.Style.Alignment.WrapText = true;
                worksheet.Cell((footerstart + 1), 1).Value = "▢ Inspected, verified and found in order as to quantity and specifications";

                //var CompCheckText = worksheet.Range("D" + (footerstart + 3) + ":D" + (footerstart + 4) + "").Merge();
                //var PartCheckText = worksheet.Range("D" + (footerstart + 5) + ":D" + (footerstart + 6) + "").Merge();

                worksheet.Cell((footerstart + 1), 3).Value = "▢ Complete";
                worksheet.Cell((footerstart + 2), 3).Value = "▢ Partial (pls. specify quantity)";


                var InspectOscarTexta = worksheet.Range("A" + (footerstart + 6) + ":B" + (footerstart + 6) + "").Merge();
                worksheet.Cell((footerstart + 6), 1).Value = dt2.Rows[0]["Receiver"].ToString();
                InspectOscarTexta.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                var InspectOscarTextab = worksheet.Range("A" + (footerstart + 7) + ":B" + (footerstart + 7) + "").Merge();
                worksheet.Cell((footerstart + 7), 1).Value = dt2.Rows[0]["ReceiverPosition"].ToString();
                InspectOscarTextab.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                var InspectOscarText = worksheet.Range("A" + (footerstart + 12) + ":B" + (footerstart + 12) + "").Merge();
                worksheet.Cell((footerstart + 12), 1).Value = "Proponent";
                InspectOscarText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;


                //var Approver = worksheet.Range("D" + (footerstart + 15) + ":F" + (footerstart + 15) + "").Merge();
                //worksheet.Cell((footerstart + 14), 4).Value = dt1.Rows[0][4];
                //Approver.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                var SupCustText = worksheet.Range("C" + (footerstart + 12) + ":E" + (footerstart + 12) + "").Merge();
                worksheet.Cell((footerstart + 12), 3).Value = dt2.Rows[0]["ApproverPosition"].ToString();
                SupCustText.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                var SupCustTexta = worksheet.Range("C" + (footerstart + 11) + ":E" + (footerstart + 11) + "").Merge();
                worksheet.Cell((footerstart + 11), 3).Value = dt2.Rows[0]["Approver"].ToString();
                SupCustTexta.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                //FOOTER END --------------------------------------------------------------------------

                //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
                foreach (var column in worksheet.ColumnsUsed())
                {
                    column.AdjustToContents();
                }

                worksheet.Column("A").Width = 9.43;
                worksheet.Column("B").Width = 33;
                worksheet.Column("C").Width = 13.57;
                worksheet.Column("D").Width = 16;
                worksheet.Column("E").Width = 15.86;
                //SAVE PATH
                using (MemoryStream ms = new MemoryStream())
                {
                    workbook.SaveAs(ms);

                    byte[] output = ms.ToArray();
                    return Convert.ToBase64String(output, 0, output.Length);
                }
            }
        }
        catch (Exception ex)
        {
            return "";
        }
    }

