    //CIIRUP
    public static string ExportToExcelIIRUP(DataTable dt)
    {
        //Get company info
        MiscBll miscBll = new MiscBll();
        string x = miscBll.GetCompanyInformation(Common.ConnString);
        CompanyName = x.Split('|')[0];
        CompanyContactNumber = x.Split('|')[3];
        CompanyAddress = x.Split('|')[5];

        string y = miscBll.GetFormHeader(Common.ConnString);
        header1 = y.Split('|')[0];
        header2 = y.Split('|')[1];
        headerHeight = y.Split('|')[2];
        headerWidth = y.Split('|')[3];

        string depreciationSetting = miscBll.GetDepreciation(Common.ConnString).Split('|')[0];

        using (var workbook = new XLWorkbook())
        {
            var worksheet = workbook.Worksheets.Add("IIRUP");
            //TITLE START
            var Appendix = worksheet.Range("P1:R1").Merge();
            //worksheet.Cell(1, 16).Value = "Appendix 74";
            Appendix.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
            Appendix.Style.Font.FontSize = 11;
            Appendix.Style.Font.Italic = true;

            var Header1 = worksheet.Range("A2:R2").Merge();
            worksheet.Cell(2, 1).Value = header1;
            Header1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            Header1.Style.Font.FontSize = 14;
            Header1.Style.Font.Bold = true;


            var Header2 = worksheet.Range("A3:R3").Merge();
            worksheet.Cell(3, 1).Value = header2;
