    //CIIRUSP
    public static string ExportToExcelCIIRUSP(DataTable dt)
    {
        //Get company info
        MiscBll miscBll = new MiscBll();
        string x = miscBll.GetCompanyInformation(Common.ConnString);
        CompanyName = x.Split('|')[0];
        CompanyContactNumber = x.Split('|')[3];
        CompanyAddress = x.Split('|')[5];

        string y = miscBll.GetFormHeader(Common.ConnString);
        header1 = y.Split('|')[0];
        header2 = y.Split('|')[1];
        headerHeight = y.Split('|')[2];
        headerWidth = y.Split('|')[3];

        string depreciationSetting = miscBll.GetDepreciation(Common.ConnString).Split('|')[0];

        using (var workbook = new XLWorkbook())
        {
            var worksheet = workbook.Worksheets.Add("IIRUSP");
            //TITLE START
            var Appendix = worksheet.Range("P1:R1").Merge();
            //worksheet.Cell(1, 16).Value = "Appendix 74";
