    //ITR
    public static string ExportToExcelITR(DataTable dt, string issuanceno, string employeename, string employeedepartment, string employeeposition, string transactorname, string transactordepartment, string transactorposition, string issueddate, string remarks, string custodian, string approvername, string fromloc, string toloc, string approverpos)
    {
        //Get company info
        MiscBll miscBll = new MiscBll();
        string x = miscBll.GetCompanyInformation(Common.ConnString);
        CompanyName = x.Split('|')[0];
        CompanyContactNumber = x.Split('|')[3];
        CompanyAddress = x.Split('|')[5];

        string y = miscBll.GetFormHeader(Common.ConnString);
        header1 = y.Split('|')[0];
        header2 = y.Split('|')[1];
        headerHeight = y.Split('|')[2];
        headerWidth = y.Split('|')[3];

        using (var workbook = new XLWorkbook())
        {
            var worksheet = workbook.Worksheets.Add("ITR");
            //TITLE START
            var Appendix = worksheet.Range("H1:I1").Merge();
            worksheet.Cell(1, 8).Value = "";
            Appendix.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Right;
            Appendix.Style.Font.Bold = true;
            Appendix.Style.Font.FontSize = 11;
            Appendix.Style.Font.Italic = true;

            var Header1 = worksheet.Range("A2:I2").Merge();
            worksheet.Cell(2, 1).Value = header1;
            Header1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            Header1.Style.Font.Bold = true;
            Header1.Style.Font.FontSize = 14;

            var Header2 = worksheet.Range("A3:I3").Merge();
            worksheet.Cell(3, 1).Value = header2;
