            worksheet.Row(19).Height = 4.5;
            worksheet.Row(35).Height = 8.25;
            worksheet.Row(40).Height = 29.25;
            worksheet.Row(50).Height = 9.75;
            worksheet.Row(55).Height = 9.75;

            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }

