            var b4 = worksheet.Range("E" + (countMax + 5) + ":G" + (countMax + 5) + "").Merge();
            worksheet.Cell((countMax + 5), 5).Value = "Signature over Printed Name of Head of  Agency/Entity or Authorized Representative";
            b4.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b4.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b4.Style.Alignment.WrapText = true;

            var b5 = worksheet.Range("I" + (countMax + 5) + ":J" + (countMax + 5) + "").Merge();
            worksheet.Cell((countMax + 5), 9).Value = "Signature over Printed Name of COA Representative";
            b5.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b5.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b5.Style.Alignment.WrapText = true;


            //FOOTER END --------------------------------------------------------------------------

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }


            worksheet.Column("A").Width = 8;
            worksheet.Column("B").Width = 16;
            worksheet.Column("C").Width = 16;
            worksheet.Column("D").Width = 11;
            worksheet.Column("E").Width = 10;
            worksheet.Column("F").Width = 10;
            worksheet.Column("G").Width = 13;
            worksheet.Column("H").Width = 13;
            worksheet.Column("K").Width = 16;

            worksheet.Row(11).Height = 30;
            worksheet.Row(countMax + 5).Height = 54;

            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }

    }
