            b1ade.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b1ade.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b1ade.Style.Alignment.WrapText = true;

            var b1awe = worksheet.Range("G" + (countMax + 10) + ":I" + (countMax + 10) + "").Merge();
            worksheet.Cell((countMax + 10), 7).Value = "Date";
            b1awe.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b1awe.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b1awe.Style.Alignment.WrapText = true;


            //FOOTER END --------------------------------------------------------------------------

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }


            worksheet.Column("A").Width = 7.13;
            worksheet.Column("B").Width = 10.88;
            worksheet.Column("C").Width = 20;
            worksheet.Column("D").Width = 10;
            worksheet.Column("E").Width = 11;
            worksheet.Column("F").Width = 11;
            worksheet.Column("G").Width = 20;
            worksheet.Column("H").Width = 13;
            worksheet.Column("I").Width = 12.75;

            worksheet.Row(3).Height = 43;
            //worksheet.Row(38).Height = 26;
            //worksheet.Row(39).Height = 21;

            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }


