                    d2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d2.Style.Alignment.WrapText = true;


                    worksheet.Range("B" + SBorder + ":C" + SBorder).Merge();
                    //worksheet.Cell(SBorder, 4).Value = dt.Rows[i]["Description"].ToString() +". " + dt.Rows[i]["LongDescription"].ToString();
                    worksheet.Cell(SBorder, 5).Value = BasePage.ConvertToMoneyFormat(dt.Rows[i]["AcquiredCost"].ToString());
                    worksheet.Cell(SBorder, 6).Value = dt.Rows[i]["PARICSnumber"].ToString();

                    worksheet.Range("A" + SBorder + ":F" + SBorder + "").Style.Border.BottomBorder = XLBorderStyleValues.Thin;
                    worksheet.Range("A" + SBorder + ":F" + SBorder + "").Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

                    double acquiredCost = 0;
                    if (double.TryParse(dt.Rows[i]["AcquiredCost"].ToString(), out acquiredCost))
                    {
                        totalAmount += acquiredCost;
                    }

                    SBorder += 1;
                }
            }

            //DETAILS END -------------------------------------------------------------------------------

            //FOOTER START

            worksheet.Cell(countMax + 3, 1).Value = "CONFORME: ";
            worksheet.Cell(countMax + 1, 5).Value = "Number of Asset: ";
            worksheet.Cell(countMax + 1, 6).Value = dt.Rows.Count;
            worksheet.Cell(countMax + 2, 5).Value = "Total Amount: ";
            worksheet.Cell(countMax + 2, 6).Value = BasePage.ConvertToMoneyFormat(totalAmount.ToString());

            var footerUnderLine = worksheet.Range("A" + (countMax + 5) + ":B" + (countMax + 5)).Merge();
            footerUnderLine.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            footerUnderLine.Style.Border.TopBorder = XLBorderStyleValues.Thin;



            //FOOTER END --------------------------------------------------------------------------

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }

            //worksheet.Column("A").Width = 12;
            worksheet.Column("B").Width = 25;
            worksheet.Column("C").Width = 5;
            worksheet.Column("D").Width = 30;
            worksheet.Column("E").Width = 15;
            worksheet.Column("F").Width = 25;
            worksheet.Column("G").Width = 20;
            worksheet.Column("H").Width = 17;

            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }

