                    d1.Style.Alignment.WrapText = true;

                    var d2 = worksheet.Cell(SBorder, 2);
                    worksheet.Cell(SBorder, 2).Value = dt.Rows[i]["LongDescription"].ToString();
                    d2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d2.Style.Alignment.WrapText = true;

                    var d3 = worksheet.Cell(SBorder, 3);
                    worksheet.Cell(SBorder, 3).Value = dt.Rows[i]["PropertyNumber"].ToString();
                    d3.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d3.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d3.Style.Alignment.WrapText = true;

                    var d4 = worksheet.Cell(SBorder, 4);
                    worksheet.Cell(SBorder, 4).Value = dt.Rows[i]["UnitOfMeasurement"].ToString();
                    d4.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d4.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d4.Style.Alignment.WrapText = true;

                    var d5 = worksheet.Cell(SBorder, 5);
                    worksheet.Cell(SBorder, 5).Value = BasePage.ConvertToMoneyFormat(dt.Rows[i]["AcquiredCost"].ToString());
                    d5.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d5.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d5.Style.Alignment.WrapText = true;


                    if (dt.Rows[i]["Status"].ToString() == "0")
                    {
                        Status = "NOT FOUND - ";
                        if (dt.Rows[i]["Area"].ToString() == "NULL" || dt.Rows[i]["Area"].ToString() == null || dt.Rows[i]["Area"].ToString() == "")
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString();
                        }
                        else
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString() + "-" + dt.Rows[i]["Area"].ToString();
                        }
                        Status1 = "1";
                        Status2 = "0";
                    }
                    else if (dt.Rows[i]["Status"].ToString() == "1")
                    {
                        quantity = "";
                        Status = "FOUND - ";
                        if (dt.Rows[i]["Area"].ToString() == "NULL" || dt.Rows[i]["Area"].ToString() == null || dt.Rows[i]["Area"].ToString() == "")
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString();
                        }
                        else
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString() + "-" + dt.Rows[i]["Area"].ToString();
                        }
                        Value = "";

                        Status1 = "1";
                        Status2 = "1";
                    }
                    else
                    {
                        Status = "MISPLACED - ";
                        if (dt.Rows[i]["Area"].ToString() == "NULL" || dt.Rows[i]["Area"].ToString() == null || dt.Rows[i]["Area"].ToString() == "")
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString();
                        }
                        else
                        {
                            Status += dt.Rows[i]["WarehouseName"].ToString() + "-" + dt.Rows[i]["Location"].ToString() + "-" + dt.Rows[i]["Area"].ToString();
                        }
                        Status = "";

                        Status1 = "1";
                        Status2 = "1";
                    }

                    var d6 = worksheet.Cell(SBorder, 6);
                    worksheet.Cell(SBorder, 6).Value = Status1;
                    d6.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d6.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d6.Style.Alignment.WrapText = true;

                    var d7 = worksheet.Cell(SBorder, 7);
                    worksheet.Cell(SBorder, 7).Value = Status2;
                    d7.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d7.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d7.Style.Alignment.WrapText = true;

                    var d8 = worksheet.Cell(SBorder, 8);
                    worksheet.Cell(SBorder, 8).Value = quantity;
                    d8.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d8.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d8.Style.Alignment.WrapText = true;


                    var d7a = worksheet.Cell(SBorder, 9);
                    worksheet.Cell(SBorder, 9).Value = Value;
                    d7a.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d7a.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d7a.Style.Alignment.WrapText = true;

                    var d8a = worksheet.Cell(SBorder, 10);
                    worksheet.Cell(SBorder, 10).Value = Status;
                    d8a.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d8a.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d8a.Style.Alignment.WrapText = true;

                    SBorder += 1;
                }
            }

            //DETAILS END -------------------------------------------------------------------------------

            //FOOTER START


            var FooterLeftRange = worksheet.Range("A" + (countMax + 1) + ":J" + (countMax + 5) + "");
            var FooterLeftBorder = FooterLeftRange.Style.Border;
            FooterLeftBorder.OutsideBorder = XLBorderStyleValues.Thin;

            //var FooterBottRange = worksheet.Range("E" + (countMax + 1) + ":E" + (countMax + 8) + "");
            //var FooterBottBorder = FooterBottRange.Style.Border;
            //FooterBottBorder.RightBorder = XLBorderStyleValues.Thin;


            worksheet.Cell(countMax + 2, 1).Value = "Certified Correct by:";
            worksheet.Cell(countMax + 2, 4).Value = "Approved by:";


            var b1a = worksheet.Range("H" + (countMax + 2) + ":I" + (countMax + 2) + "").Merge();
            worksheet.Cell((countMax + 2), 8).Value = "Verified by:";
            b1a.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;


            //var b1b = worksheet.Range("A46:E46").Merge();
            //worksheet.Cell(44, 6).Value = "Received by:";
            //b1b.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Left;
            worksheet.Cell(countMax + 4, 2).Value = "________________________";

            var b1 = worksheet.Range("E" + (countMax + 4) + ":G" + (countMax + 4) + "").Merge();
            worksheet.Cell((countMax + 4), 5).Value = "______________________________________";
            b1.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;

            var b3 = worksheet.Range("I" + (countMax + 4) + ":J" + (countMax + 4) + "").Merge();
            worksheet.Cell((countMax + 4), 9).Value = "_______________________________";



            var b2 = worksheet.Range("B" + (countMax + 5) + ":C" + (countMax + 5) + "").Merge();
            worksheet.Cell((countMax + 5), 2).Value = "Signature over Printed Name of Inventory Committee Chair and Members";
            b2.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b2.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b2.Style.Alignment.WrapText = true;

            var b4 = worksheet.Range("E" + (countMax + 5) + ":G" + (countMax + 5) + "").Merge();
            worksheet.Cell((countMax + 5), 5).Value = "Signature over Printed Name of Head of  Agency/Entity or Authorized Representative";
            b4.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b4.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b4.Style.Alignment.WrapText = true;

            var b5 = worksheet.Range("I" + (countMax + 5) + ":J" + (countMax + 5) + "").Merge();
            worksheet.Cell((countMax + 5), 9).Value = "Signature over Printed Name of COA Representative";
            b5.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
            b5.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
            b5.Style.Alignment.WrapText = true;





            //FOOTER END --------------------------------------------------------------------------

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }


            worksheet.Column("A").Width = 8;
            worksheet.Column("B").Width = 16;
            worksheet.Column("C").Width = 16;
            worksheet.Column("D").Width = 11;
            worksheet.Column("E").Width = 10;
            worksheet.Column("F").Width = 10;
            worksheet.Column("G").Width = 13;
            worksheet.Column("H").Width = 13;

            worksheet.Row(11).Height = 36;
            worksheet.Row(countMax + 5).Height = 50;


            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }

