                        tType = dt.Rows[i]["TransNum"].ToString() + "  /  " + dt.Rows[i]["PropertyNumber"].ToString() + "  /  " + dt.Rows[i]["OfficeOfficer"].ToString() + "  /  " + dt.Rows[i]["Remarks"].ToString().Replace("</br>", " ");
                    }



