                    d5.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d5.Style.Alignment.WrapText = true;

                    worksheet.Range("F" + SBorder + ":G" + SBorder).Merge();

                    var d6a = worksheet.Cell(SBorder, 8);
                    worksheet.Cell(SBorder, 8).Value = balanceqty;
                    d6a.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d6a.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d6a.Style.Alignment.WrapText = true;

                    var d6 = worksheet.Cell(SBorder, 9);
                    worksheet.Cell(SBorder, 9).Value = BasePage.ConvertToMoneyFormat(dt.Rows[i]["Amount"].ToString());
                    d6.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d6.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d6.Style.Alignment.WrapText = true;


                    var d7 = worksheet.Cell(SBorder, 10);
                    worksheet.Cell(SBorder, 10).Value = tType;
                    d7.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;
                    d7.Style.Alignment.Vertical = XLAlignmentVerticalValues.Center;
                    d7.Style.Alignment.WrapText = true;



                    worksheet.Range("A" + SBorder + ":J" + SBorder + "").Style.Border.BottomBorder = XLBorderStyleValues.Thin;
                    worksheet.Range("A" + SBorder + ":J" + SBorder + "").Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;




                    SBorder += 1;
                }
            }

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }
            int tableRowCount = 30;
            int totalColumns = 10;
            for (int rowNum = 13; rowNum <= tableRowCount; rowNum++)
            {
                var row = worksheet.Row(rowNum);
                for (int colNum = 2; colNum <= totalColumns; colNum++)
                {
                    if (colNum == 6 || colNum == 7)
                    {
                        var OfficeOfficer = worksheet.Range(worksheet.Cell(rowNum, 6), worksheet.Cell(rowNum, 7)).Merge();
                        var OfficeOfficerBorder = OfficeOfficer.Style.Border;
                        OfficeOfficerBorder.OutsideBorder = XLBorderStyleValues.Thin;
                        OfficeOfficerBorder.InsideBorder = XLBorderStyleValues.Thin;
                        colNum = 7;
                    }
                    else
                    {
                        var cell = row.Cell(colNum);
                        var cellBorders = cell.Style.Border;
                        cellBorders.OutsideBorder = XLBorderStyleValues.Thin;
                        cellBorders.InsideBorder = XLBorderStyleValues.Thin;
                    }
                }
            }
            var DateCol = worksheet.Range("B13:B" + tableRowCount + "");
            var DateColBorder = DateCol.Style.Border;
            DateColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var ReferenceCol = worksheet.Range("C13:C" + tableRowCount + "");
            var ReferenceColBorder = ReferenceCol.Style.Border;
            ReferenceColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var ReceiptQtyCol = worksheet.Range("D13:D" + tableRowCount + "");
            var ReceiptQtyColBorder = ReceiptQtyCol.Style.Border;
            ReceiptQtyColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var ITDCol = worksheet.Range("E13:G" + tableRowCount + "");
            var ITDColBorder = ITDCol.Style.Border;
            ITDColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var BalanceQty = worksheet.Range("H13:H" + tableRowCount + "");
            var BalanceQtyBorder = BalanceQty.Style.Border;
            BalanceQtyBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var AmountCol = worksheet.Range("I13:I" + tableRowCount + "");
            var AmountColBorder = AmountCol.Style.Border;
            AmountColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            var RemarksCol = worksheet.Range("J13:J" + tableRowCount + "");
            var RemarksColBorder = RemarksCol.Style.Border;
            RemarksColBorder.OutsideBorder = XLBorderStyleValues.Medium;
            worksheet.Row(7).Height = 8;
            worksheet.Row(8).Height = 14;
            worksheet.Row(9).Height = 16.50;
            worksheet.Row(10).Height = 27;
            worksheet.Column("A").Width = 6.38;
            worksheet.Column("B").Width = 10;
            worksheet.Column("C").Width = 13.58;
            worksheet.Column("D").Width = 10;
            worksheet.Column("E").Width = 10;
            worksheet.Column("F").Width = 15.38;
            worksheet.Column("G").Width = 16.88;
            worksheet.Column("H").Width = 10;
            worksheet.Column("I").Width = 16.38;
            worksheet.Column("J").Width = 19.25;
            //SAVE PATH
            //var DateTimeNow = DateTime.Now.ToString("yyyy-MM-dd hhmmss");
            //var FileName = "PC";
            //var Directory = "D:\\ExcelReports\\";
            //workbook.SaveAs(Directory + FileName + "_" + DateTime.Now.ToString("yyyy_MM_dd_hhmmss") + ".xlsx");
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);
                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }

