            //c6.Style.Alignment.Horizontal = XLAlignmentHorizontalValues.Center;


            //FOOTER END --------------------------------------------------------------------------

            //ADJUST ALL CELLS ACCORDING TO TEXT INSIDE
            foreach (var column in worksheet.ColumnsUsed())
            {
                column.AdjustToContents();
            }

            //worksheet.Column("A").Width = 12;
            worksheet.Column("B").Width = 25;
            worksheet.Column("C").Width = 15;
            worksheet.Column("D").Width = 15;
            worksheet.Column("E").Width = 15;
            worksheet.Column("F").Width = 15;
            worksheet.Column("G").Width = 20;
            worksheet.Column("H").Width = 15;
            worksheet.Column("I").Width = 15;
            worksheet.Column("J").Width = 15;

            //SAVE PATH
            using (MemoryStream ms = new MemoryStream())
            {
                workbook.SaveAs(ms);

                byte[] output = ms.ToArray();
                return Convert.ToBase64String(output, 0, output.Length);
            }
        }
    }
